#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 100001

typedef struct {
    int *children;
    int child_count;
    int voters;
} Node;

Node tree[MAX_N];
int n;

int min_votes(int node) {
    if (tree[node].child_count == 0) {
        // Leaf node: need majority of voters
        return tree[node].voters / 2 + 1;
    }

    // For non-leaf: need to win majority of sub-districts
    int num_children = tree[node].child_count;
    int need_wins = num_children / 2 + 1; // majority of children

    // Collect votes needed from each child
    int *votes_needed = malloc(sizeof(int) * num_children);
    for (int i = 0; i < num_children; i++) {
        votes_needed[i] = min_votes(tree[node].children[i]);
    }

    // Sort to pick the smallest 'need_wins' values
    for (int i = 0; i < num_children - 1; i++) {
        for (int j = 0; j < num_children - i - 1; j++) {
            if (votes_needed[j] > votes_needed[j + 1]) {
                int temp = votes_needed[j];
                votes_needed[j] = votes_needed[j + 1];
                votes_needed[j + 1] = temp;
            }
        }
    }

    int total = 0;
    for (int i = 0; i < need_wins; i++) {
        total += votes_needed[i];
    }

    free(votes_needed);
    return total;
}

