typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

/*
We process a rooted hierarchy.
For a leaf with v voters:
  minimum votes to win it = floor(v/2) + 1

For an internal node with k children:
  to win this node, need to win t = floor(k/2) + 1 children.
  If child i requires cost[i] votes to guarantee winning that child,
  then minimum to win current node is the sum of the t smallest cost[i].
*/

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        int *m = (int *)malloc((n + 1) * sizeof(int));
        int **children = (int **)malloc((n + 1) * sizeof(int *));
        ll *cost = (ll *)malloc((n + 1) * sizeof(ll));

        for (int i = 1; i <= n; i++) {
            scanf("%d", &m[i]);
            if (m[i] > 0) {
                children[i] = (int *)malloc(m[i] * sizeof(int));
                for (int j = 0; j < m[i]; j++) {
                    scanf("%d", &children[i][j]);
                }
            } else {
                children[i] = NULL;
            }
        }

        for (int i = n; i >= 1; i--) {
            if (m[i] == 0) {
                int voters;
                scanf("%d", &voters);
                cost[i] = (ll)voters / 2 + 1;
            } else {
                ll *arr = (ll *)malloc(m[i] * sizeof(ll));
                for (int j = 0; j < m[i]; j++) {
                    arr[j] = cost[children[i][j]];
                }
                qsort(arr, m[i], sizeof(ll), cmp_ll);
                int need = m[i] / 2 + 1;
                ll sum = 0;
                for (int j = 0; j < need; j++) sum += arr[j];
                cost[i] = sum;
                free(arr);
            }
        }

        printf("%lld\n", cost[1]);

        for (int i = 1; i <= n; i++) free(children[i]);
        free(children);
        free(m);
        free(cost);
    }
    return 0;
}

