            for (int j = 0; j < m; ++j) cin >> child[j];

            if (i == 1) {
                // Leaf district: child[0] is number of voters.
                int64 voters = child[0];
                dp[i] = voters / 2 + 1;
            } else {
                // Need majority of sub-districts.
                vector<int64> costs;
                costs.reserve(m);
                for (int j = 0; j < m; ++j) costs.push_back(dp[child[j]]);

                sort(costs.begin(), costs.end());
                int need = m / 2 + 1;
                int64 sum = 0;
                for (int j = 0; j < need; ++j) sum += costs[j];
                dp[i] = sum;
            }
        }

        cout << dp[n] << '\n';
