import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        boolean first = true;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            String[] parts = line.split(" ");
            int n = Integer.parseInt(parts[0]);
            if (n == 0) break;

            int[] voters = new int[n];
            for (int i = 0; i < n; i++) {
                voters[i] = Integer.parseInt(parts[i + 1]);
            }

            System.out.println(minVotesToWin(voters));
        }
    }

    private static int minVotesToWin(int[] voters) {
        // The strategy: to win at each level, you need majority of districts,
        // and within each district you need majority of votes.
        // Sort the voters array in ascending order.
        // At the top level (president), you need to win majority of states.
        // This is a greedy bottom-up approach.

        List<Integer> level = new ArrayList<>();
        for (int v : voters) level.add(v);

        while (level.size() > 1) {
            Collections.sort(level);
            int needed = level.size() / 2 + 1; // majority of districts
            int sum = 0;
            for (int i = 0; i < needed; i++) {
                sum += level.get(i);
            }
            // The new "district" size is sum of votes from the smallest needed districts
            // But for winning, we need majority in each of those districts.
            // Actually we need to compute votes needed to win each of those districts:
            // For a district with v voters, you need v/2 + 1 votes to win it.
            int totalVotes = 0;
            for (int i = 0; i < needed; i++) {
                int v = level.get(i);
                totalVotes += v / 2 + 1;
            }
            // The next level consists of this combined unit
            List<Integer> nextLevel = new ArrayList<>();
            nextLevel.add(totalVotes);
            for (int i = needed; i < level.size(); i++) {
                nextLevel.add(level.get(i));
            }
            level = nextLevel;
        }

        // At the final level (single district left), we need majority of its votes
        return level.get(0) / 2 + 1;
    }
}

