/*
We have a hierarchical election tree.
- Leaves: electoral districts with a given number of eligible voters.
  To win a leaf, candidate needs strict majority of voters: floor(v/2) + 1.
- Internal node: consists of several sub-districts from previous stage.
  To win it, candidate must win a strict majority of its children:
  floor(k/2) + 1 children.

Minimum votes needed to guarantee winning a node:
- Leaf: floor(v/2) + 1
- Internal: if children costs are c1..ck, we need to win t = floor(k/2)+1 children,
  choosing the cheapest ones. So cost = sum of smallest t child costs.

Input format (standard for this classic problem):
Multiple datasets.
Each dataset:
  n
  then for i = 1..n:
    m a1 a2 ... am
If m = 0, node i is a leaf and the next integer is its number of voters.
Otherwise node i is an internal node with m children listed after it.
Datasets end with n = 0.

Nodes are given so that children have larger indices than parent in this problem's usual formulation,
thus we can compute DP from n down to 1.

Output one line per dataset: minimum votes needed to win the whole election (node 1).
*/
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            if (n == 0) break;

            int[][] children = new int[n + 1][];
            int[] leafVotes = new int[n + 1];
            boolean[] isLeaf = new boolean[n + 1];

            for (int i = 1; i <= n; i++) {
                int m = fs.nextInt();
                if (m == 0) {
                    isLeaf[i] = true;
                    leafVotes[i] = fs.nextInt();
                } else {
                    children[i] = new int[m];
                    for (int j = 0; j < m; j++) {
                        children[i][j] = fs.nextInt();
                    }
                }
            }

            long[] dp = new long[n + 1];

            for (int i = n; i >= 1; i--) {
                if (isLeaf[i]) {
                    dp[i] = leafVotes[i] / 2 + 1;
                } else {
                    int[] ch = children[i];
                    long[] costs = new long[ch.length];
                    for (int j = 0; j < ch.length; j++) {
                        costs[j] = dp[ch[j]];
                    }
                    Arrays.sort(costs);
                    int need = ch.length / 2 + 1;
                    long sum = 0;
                    for (int j = 0; j < need; j++) sum += costs[j];
                    dp[i] = sum;
                }
            }

            out.append(dp[1]).append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(map(int, data))
    out = []

    while True:
        try:
            n = next(it)
        except StopIteration:
            break

        # dp[i] = minimum votes needed to guarantee winning district i
        # Districts are numbered 1..n in input order.
        dp = [0] * (n + 1)

        for i in range(1, n + 1):
            k = next(it)
            if k == 0:
                # Leaf district: next number is number of voters
                voters = next(it)
                dp[i] = voters // 2 + 1
            else:
                children = [next(it) for _ in range(k)]
                need = k // 2 + 1
                costs = sorted(dp[c] for c in children)
                dp[i] = sum(costs[:need])

        out.append(str(dp[n]))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
